<section class="site-page-heading"><div class="container"><p class="site-kicker"><?php foreach ($breadcrumb as $crumb): ?><a href="<?= \FangdaysCMS\Cms\View::e(\FangdaysCMS\Cms\View::categoryLink($crumb)) ?>"><?= \FangdaysCMS\Cms\View::e($crumb['name']) ?></a> / <?php endforeach; ?><?= date('Y-m-d', (int) $post['published_at']) ?></p><h1<?= $post['title_color'] !== '' ? ' style="color:' . \FangdaysCMS\Cms\View::e($post['title_color']) . '"' : '' ?>><?= \FangdaysCMS\Cms\View::e($post['title']) ?></h1><?php if ($post['subtitle'] !== ''): ?><p class="lead mb-2"><?= \FangdaysCMS\Cms\View::e($post['subtitle']) ?></p><?php endif; ?><?php if ($post['author'] !== '' || $post['source'] !== ''): ?><p class="mb-0 small text-muted"><?php if ($post['author'] !== ''): ?>作者：<?= \FangdaysCMS\Cms\View::e($post['author']) ?><?php endif; ?><?php if ($post['source'] !== ''): ?>　来源：<?= \FangdaysCMS\Cms\View::e($post['source']) ?><?php endif; ?></p><?php endif; ?></div></section>
<div class="container py-5"><div class="row justify-content-center"><article class="col-lg-9">
  <?php if ($post['cover_path']): ?><img class="site-post-cover mb-4" src="<?= \FangdaysCMS\Cms\View::e($post['cover_path']) ?>" alt="<?= \FangdaysCMS\Cms\View::e($post['title']) ?>"><?php endif; ?>
  <?php if ($tags): ?><div class="site-tags mb-4"><?php foreach ($tags as $tag): ?><a href="/tag/<?= \FangdaysCMS\Cms\View::e($tag['slug']) ?>">#<?= \FangdaysCMS\Cms\View::e($tag['name']) ?></a><?php endforeach; ?></div><?php endif; ?>
  <div class="site-article-body"><?= \FangdaysCMS\Cms\RichText::render($post['body'], $post['body_format']) ?></div>
  <?php if ($gallery): ?><section class="site-post-gallery mt-4" aria-label="文章多图"><h2>图片集</h2><div class="site-post-gallery-grid"><?php foreach ($gallery as $image): ?><figure><img src="<?= \FangdaysCMS\Cms\View::e($image['path']) ?>" alt="<?= \FangdaysCMS\Cms\View::e($image['title'] ?: $image['original_name']) ?>" loading="lazy"><figcaption><?= \FangdaysCMS\Cms\View::e($image['title'] ?: $image['original_name']) ?></figcaption></figure><?php endforeach; ?></div></section><?php endif; ?>
  <?php if ($attachment): ?><p class="site-post-attachment mt-4"><a href="/post/<?= \FangdaysCMS\Cms\View::e($post['slug']) ?>/attachment">下载附件：<?= \FangdaysCMS\Cms\View::e($attachment['original_name']) ?></a> <small>（<?= (int) $attachment['bytes'] ?> 字节）</small></p><?php endif; ?>
  <?php if ($extra_fields): ?><dl class="site-post-fields mt-4 border-top pt-3"><?php foreach ($extra_fields as $field): ?><div class="row py-2"><dt class="col-sm-3"><?= \FangdaysCMS\Cms\View::e($field['label']) ?></dt><dd class="col-sm-9 mb-0"><?php if ($field['type'] === 'editor'): ?><?= \FangdaysCMS\Cms\RichText::render($field['value'], 'html') ?><?php elseif ($field['type'] === 'image'): ?><img class="site-post-cover" src="<?= \FangdaysCMS\Cms\View::e($field['value']) ?>" alt="<?= \FangdaysCMS\Cms\View::e($field['label']) ?>"><?php else: ?><?= nl2br(\FangdaysCMS\Cms\View::e($field['value'])) ?><?php endif; ?></dd></div><?php endforeach; ?></dl><?php endif; ?>
  <p class="mt-5"><a href="/">← 返回首页</a></p>
</article></div></div>
